// Filter the sheet rows down to the last 7 days and build a compact
// metrics block the AI can reason over. Tolerant of column-name casing.
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && Object.keys(r).some(k => r[k] !== '' && r[k] !== null && r[k] !== undefined));

const now = new Date();
const weekEnd = now;
const weekStart = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d;
}

const pick = (r, names) => {
  for (const n of names) {
    if (r[n] !== undefined && r[n] !== null && r[n] !== '') return r[n];
  }
  return '';
};

const thisWeek = rows.filter(r => {
  const d = parseDate(pick(r, ['Date', 'date', 'DATE']));
  return d && d >= weekStart && d <= weekEnd;
});

const fmt = d => d.toISOString().slice(0, 10);

const lines = thisWeek.map(r => {
  const metric = pick(r, ['Metric', 'metric']) || 'Metric';
  const value = pick(r, ['Value', 'value']);
  const notes = pick(r, ['Notes', 'notes']);
  const date = pick(r, ['Date', 'date', 'DATE']);
  return metric + ': ' + value + (notes ? ' — ' + notes : '') + ' [' + date + ']';
});

return [{
  json: {
    rowCount: thisWeek.length,
    totalRowsInSheet: rows.length,
    weekOf: fmt(weekStart),
    weekRange: fmt(weekStart) + ' to ' + fmt(weekEnd),
    metricsBlock: lines.join('\n')
  }
}];

// Safely parse the AI's JSON and build a polished HTML email + a plain-text
// archive copy. If the AI ever returns malformed JSON, we fall back to a
// simple-but-safe report instead of failing the run.
const cfg = $('Workflow Config').item.json;
const week = $('Summarize the Week').item.json;
const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';

let report;
try {
  const cleaned = String(raw).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  report = JSON.parse(cleaned);
  if (typeof report !== 'object' || report === null) throw new Error('AI did not return an object');
} catch (e) {
  report = {
    subject: 'Weekly Report — ' + cfg.clientName + ' (week of ' + week.weekOf + ')',
    intro: raw ? String(raw) : 'Here is a summary of the metrics we tracked for you this week.',
    wins: [],
    numbers: [],
    next_week: [],
    closing: 'Reply to this email if you have any questions — happy to walk through anything.'
  };
}

const esc = s => String(s === undefined || s === null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const wins = Array.isArray(report.wins) ? report.wins : [];
const numbers = Array.isArray(report.numbers) ? report.numbers : [];
const nextWeek = Array.isArray(report.next_week) ? report.next_week : [];

const h2 = t => '<h2 style="font-size:15px;color:#111827;margin:24px 0 8px;">' + t + '</h2>';
const li = s => '<li style="margin:0 0 8px;">' + esc(s) + '</li>';

const winsHtml = wins.length
  ? h2('Wins this week') + '<ul style="margin:0;padding-left:20px;">' + wins.map(li).join('') + '</ul>'
  : '';

const numRows = numbers.map(n => '<tr>'
  + '<td style="padding:8px 12px;border-bottom:1px solid #e5e7eb;font-weight:bold;white-space:nowrap;">' + esc(n.label) + '</td>'
  + '<td style="padding:8px 12px;border-bottom:1px solid #e5e7eb;white-space:nowrap;">' + esc(n.value) + '</td>'
  + '<td style="padding:8px 12px;border-bottom:1px solid #e5e7eb;color:#4b5563;">' + esc(n.context) + '</td>'
  + '</tr>').join('');

const numbersHtml = numbers.length
  ? h2('The numbers') + '<table style="border-collapse:collapse;width:100%;font-size:13px;">' + numRows + '</table>'
  : '';

const nextHtml = nextWeek.length
  ? h2('Next week') + '<ul style="margin:0;padding-left:20px;">' + nextWeek.map(li).join('') + '</ul>'
  : '';

const htmlBody = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:0 auto;color:#1f2937;font-size:14px;line-height:1.55;">'
  + '<div style="background:#111827;color:#ffffff;padding:22px 28px;border-radius:8px 8px 0 0;">'
  + '<h1 style="margin:0;font-size:19px;">Weekly Report — ' + esc(cfg.clientName) + '</h1>'
  + '<p style="margin:6px 0 0;color:#9ca3af;font-size:12px;">Week of ' + esc(week.weekRange) + ' · Prepared by ' + esc(cfg.agencyName) + '</p>'
  + '</div>'
  + '<div style="border:1px solid #e5e7eb;border-top:none;padding:24px 28px;border-radius:0 0 8px 8px;background:#ffffff;">'
  + '<p style="margin:0;">' + esc(report.intro) + '</p>'
  + winsHtml + numbersHtml + nextHtml
  + '<p style="margin:24px 0 0;">' + esc(report.closing) + '</p>'
  + '<p style="margin:18px 0 0;color:#6b7280;">— The ' + esc(cfg.agencyName) + ' team</p>'
  + '</div></div>';

const textParts = [];
textParts.push('WEEKLY REPORT — ' + cfg.clientName + ' (' + week.weekRange + ')');
textParts.push('');
textParts.push(String(report.intro || ''));
if (wins.length) { textParts.push(''); textParts.push('WINS THIS WEEK'); wins.forEach(w => textParts.push('- ' + w)); }
if (numbers.length) { textParts.push(''); textParts.push('THE NUMBERS'); numbers.forEach(n => textParts.push('- ' + n.label + ': ' + n.value + (n.context ? ' (' + n.context + ')' : ''))); }
if (nextWeek.length) { textParts.push(''); textParts.push('NEXT WEEK'); nextWeek.forEach(w => textParts.push('- ' + w)); }
if (report.closing) { textParts.push(''); textParts.push(String(report.closing)); }

return [{
  json: {
    subject: report.subject || ('Weekly Report — ' + cfg.clientName + ' (week of ' + week.weekOf + ')'),
    htmlBody: htmlBody,
    reportText: textParts.join('\n'),
    weekOf: week.weekOf,
    weekRange: week.weekRange
  }
}];
